namespace sv_6d9fc6b18d294984ab3850e640900d2f.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@rendermode InteractiveServer
@using sv_6d9fc6b18d294984ab3850e640900d2f.Services
@inject IProductService ProductService
@inject NavigationManager Navigation

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <div class="row">
        @* ───── Left Sidebar (Filters) ───── *@
        <div class="col-md-3">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    @* Categories *@
                    <h6>Category</h6>
                    @if (categories is not null)
                    {
                        @foreach (var cat in categories)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                       checked="@selectedCategories.Contains(cat)"
                                       @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                                <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                            </div>
                        }
                    }

                    <hr />

                    @* Price Range *@
                    <h6>Price Range</h6>
                    <div class="mb-2">
                        <label class="form-label form-label-sm">Min</label>
                        <input type="number" class="form-control form-control-sm" placeholder="0"
                               @bind="minPrice" @bind:event="oninput" min="0" step="0.01" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label form-label-sm">Max</label>
                        <input type="number" class="form-control form-control-sm" placeholder="Any"
                               @bind="maxPrice" @bind:event="oninput" min="0" step="0.01" />
                    </div>

                    <hr />

                    @* In Stock Only *@
                    <div class="form-check form-switch mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly"
                               @bind="inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    @* Action Buttons *@
                    <button class="btn btn-primary w-100 mb-2" @onclick="ApplyFilters">
                        Apply Filters
                    </button>
                    <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">
                        Clear Filters
                    </button>
                </div>
            </div>
        </div>

        @* ───── Main Content ───── *@
        <div class="col-md-9">
            @if (errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">
                    <strong>Error:</strong> @errorMessage
                </div>
            }
            else if (isLoading)
            {
                <div class="d-flex justify-content-center align-items-center py-5">
                    <div class="spinner-border text-primary me-2" role="status"></div>
                    <span>Loading products…</span>
                </div>
            }
            else if (result is null || result.Items.Count == 0)
            {
                <div class="text-center py-5 text-muted">
                    <h4>No products found</h4>
                    <p>Try adjusting your filters.</p>
                </div>
            }
            else
            {
                @* Toolbar *@
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <div>
                        <label class="form-label me-2 mb-0">Sort by:</label>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                @onchange="OnSortChanged">
                            @foreach (var opt in sortOptions)
                            {
                                <option value="@opt.Value" selected="@(sortBy == opt.Value)">@opt.Label</option>
                            }
                        </select>
                    </div>
                    <span class="text-muted">
                        Showing @(StartItem)–@(EndItem) of @result.TotalCount products
                    </span>
                </div>

                @* Product Grid *@
                <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
                    @foreach (var product in result.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product"
                                         OnProductSelected="OnProductSelected"
                                         OnAddToCart="OnAddToCart" />
                        </div>
                    }
                </div>

                @* Pagination *@
                @if (TotalPages > 1)
                {
                    <nav class="mt-4" aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
                                        disabled="@(currentPage == 1)">
                                    Previous
                                </button>
                            </li>
                            @for (int i = 1; i <= TotalPages; i++)
                            {
                                var page = i;
                                <li class="page-item @(page == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(page)">@page</button>
                                </li>
                            }
                            <li class="page-item @(currentPage == TotalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
                                        disabled="@(currentPage == TotalPages)">
                                    Next
                                </button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
</div>

@code {
    // ── Filter state ──
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // ── Sort / page state ──
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;

    // ── Results ──
    private PagedResult<Product>? result;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly (string Value, string Label)[] sortOptions =
    {
        ("price_asc",   "Price: Low to High"),
        ("price_desc",  "Price: High to Low"),
        ("name_asc",    "Name: A-Z"),
        ("rating_desc", "Rating: Highest"),
    };

    private int TotalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int StartItem => (result!.Page - 1) * PageSize + 1;
    private int EndItem   => Math.Min(result!.Page * PageSize, result.TotalCount);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;
        StateHasChanged();

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked) selectedCategories.Add(category);
        else selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        sortBy = "price_asc";
        await LoadProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await LoadProducts();
    }

    private void OnProductSelected(Product product)
    {
        Navigation.NavigateTo($"/product/{product.Id}");
    }

    private void OnAddToCart(Product product)
    {
        // Placeholder for cart integration
    }
}

@using sv_6d9fc6b18d294984ab3850e640900d2f.Services

<div class="card h-100 product-card" @onclick="HandleCardClick" role="button">
    @* Placeholder image *@
    <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
         style="height:180px;" role="img" aria-label="@Product.Name">
        <span class="text-muted small">@Product.Name</span>
    </div>

    <div class="card-body d-flex flex-column">
        <h6 class="card-title mb-1">@Product.Name</h6>
        <p class="fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <p class="mb-2">
            @GetStarRating(Product.Rating)
        </p>

        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }

        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

